mapper.select:
SELECT
    id,
    actor_id,
    actor_username,
    actor_role,
    action,
    target_type,
    target_id,
    target_label,
    result,
    error_code,
    occurred_at,
    trace_id
FROM farm_audit_log

    AND actor_id = #{query.actorId}
    AND action = #{query.action}
    AND target_type = #{query.targetType}
    AND target_id = #{query.targetId}
    AND result = #{query.result}
    AND occurred_at >= #{query.from}
    AND occurred_at <= #{query.to}

ORDER BY occurred_at DESC, id DESC
